// Extraer información completa del error desde el contexto del Error Trigger
const errData = $input.item.json;

// Nombre del workflow donde ocurrió el error
const workflow = errData.workflow?.name ?? 'Desconocido';

// Nodo donde ocurrió el error
const paso = errData.execution?.lastNodeExecuted ?? 'Desconocido';

// Mensaje de error
const errorMsg = errData.error?.message ?? 'Sin mensaje de error';

// ID de ejecución
const executionId = errData.execution?.id ?? 'N/A';

// Modo de ejecución (manual, trigger, etc.)
const mode = errData.execution?.mode ?? 'N/A';

// Stack trace si existe
const stack = errData.error?.stack ?? '';

// Payload: información útil del contexto del error
const payload = {
    workflow_id: errData.workflow?.id ?? null,
    execution_id: executionId,
    mode: mode,
    last_node: paso,
    error_name: errData.error?.name ?? 'Error',
    stack_trace: stack.substring(0, 500), // Limitar a 500 chars
    timestamp: new Date().toISOString()
};

// Línea para el archivo de log (formato legible)
const timestamp = new Date().toISOString();
const logLine = `[${timestamp}] ERROR en "${workflow}" | Nodo: "${paso}" | Msg: ${errorMsg} | ExecID: ${executionId}\n`;

return [{
    json: {
        workflow,
        paso,
        errorMsg,
        payload,
        logLine
    }
}];

// Construir el contenido a escribir en el archivo de log
const logLine = $('Extraer Datos del Error').item.json.logLine;

// Convertir el texto a Buffer binario (requerido por Write Binary File)
const buffer = Buffer.from(logLine, 'utf8');

return [{
    json: {},
    binary: {
        data: {
            data: buffer.toString('base64'),
            mimeType: 'text/plain',
            fileName: 'errors.log'
        }
    }
}];
